-- Normalisasi negara film (diagnosis 2026-11-28): enrich Hashflix
-- menyimpan kode ISO (ID/US) dari production_countries, sementara
-- katalog memakai nama Indonesia ("Indonesia", "Amerika Serikat").
-- Samakan baris lama ke nama; ke depan parseHFDetails + stempel
-- live-browse menulis nama langsung.
-- Sekalian: semua film yang tersimpan 'ongoing' (hasil impor/discover)
-- jadi 'completed' — film adalah karya tunggal yang tamat, bukan
-- serial berjalan ("Berlanjut" di halaman Detail film itu salah).
update titles set country = case country when 'DZ' then 'Aljazair' when 'AL' then 'Albania' when 'US' then 'Amerika Serikat' when 'AO' then 'Angola' when 'AR' then 'Argentina' when 'AM' then 'Armenia' when 'AU' then 'Australia' when 'AT' then 'Austria' when 'AZ' then 'Azerbaijan' when 'BH' then 'Bahrain' when 'BD' then 'Bangladesh' when 'BE' then 'Belgia' when 'BO' then 'Bolivia' when 'BA' then 'Bosnia dan Herzegovina' when 'BW' then 'Botswana' when 'BR' then 'Brasil' when 'BG' then 'Bulgaria' when 'CM' then 'Kamerun' when 'CA' then 'Kanada' when 'KZ' then 'Kazakhstan' when 'KE' then 'Kenya' when 'CL' then 'Chile' when 'CN' then 'China' when 'CI' then 'Pantai Gading' when 'CO' then 'Kolombia' when 'KR' then 'Korea Selatan' when 'CR' then 'Kosta Rika' when 'HR' then 'Kroasia' when 'CU' then 'Kuba' when 'KW' then 'Kuwait' when 'KG' then 'Kirgistan' when 'LA' then 'Laos' when 'LV' then 'Latvia' when 'LB' then 'Lebanon' when 'LT' then 'Lituania' when 'LU' then 'Luksemburg' when 'MG' then 'Madagaskar' when 'MY' then 'Malaysia' when 'MT' then 'Malta' when 'MA' then 'Maroko' when 'MX' then 'Meksiko' when 'EG' then 'Mesir' when 'MN' then 'Mongolia' when 'MZ' then 'Mozambik' when 'MM' then 'Myanmar' when 'NA' then 'Namibia' when 'NP' then 'Nepal' when 'NL' then 'Belanda' when 'NZ' then 'Selandia Baru' when 'NG' then 'Nigeria' when 'NO' then 'Norwegia' when 'OM' then 'Oman' when 'PK' then 'Pakistan' when 'PS' then 'Palestina' when 'PY' then 'Paraguay' when 'PE' then 'Peru' when 'PH' then 'Filipina' when 'PL' then 'Polandia' when 'PT' then 'Portugal' when 'FR' then 'Prancis' when 'PR' then 'Puerto Riko' when 'QA' then 'Qatar' when 'DO' then 'Republik Dominika' when 'CZ' then 'Ceko' when 'RO' then 'Rumania' when 'RU' then 'Rusia' when 'SA' then 'Arab Saudi' when 'SN' then 'Senegal' when 'RS' then 'Serbia' when 'SG' then 'Singapura' when 'SK' then 'Slowakia' when 'SI' then 'Slovenia' when 'ES' then 'Spanyol' when 'LK' then 'Sri Lanka' when 'ZA' then 'Afrika Selatan' when 'SU' then 'Uni Soviet' when 'SY' then 'Suriah' when 'CH' then 'Swiss' when 'SE' then 'Swedia' when 'TW' then 'Taiwan' when 'TJ' then 'Tajikistan' when 'TH' then 'Thailand' when 'TM' then 'Turkmenistan' when 'TN' then 'Tunisia' when 'TR' then 'Turki' when 'UA' then 'Ukraina' when 'AE' then 'Uni Emirat Arab' when 'UY' then 'Uruguay' when 'UZ' then 'Uzbekistan' when 'VE' then 'Venezuela' when 'VN' then 'Vietnam' when 'YE' then 'Yaman' when 'JO' then 'Yordania' when 'GR' then 'Yunani' when 'ET' then 'Etiopia' when 'GH' then 'Ghana' when 'HK' then 'Hong Kong' when 'IN' then 'India' when 'ID' then 'Indonesia' when 'GB' then 'Inggris' when 'IQ' then 'Irak' when 'IR' then 'Iran' when 'IE' then 'Irlandia' when 'IS' then 'Islandia' when 'IL' then 'Israel' when 'IT' then 'Italia' when 'JM' then 'Jamaika' when 'JP' then 'Jepang' when 'DE' then 'Jerman' when 'GE' then 'Georgia' when 'FI' then 'Finlandia' when 'HU' then 'Hungaria' when 'DK' then 'Denmark' when 'EE' then 'Estonia' when 'EC' then 'Ekuador' when 'KH' then 'Kamboja' when 'CY' then 'Siprus' when 'MC' then 'Monako' when 'MK' then 'Makedonia Utara' when 'ZW' then 'Zimbabwe' when 'ZM' then 'Zambia' end
where country in ('DZ','AL','US','AO','AR','AM','AU','AT','AZ','BH','BD','BE','BO','BA','BW','BR','BG','CM','CA','KZ','KE','CL','CN','CI','CO','KR','CR','HR','CU','KW','KG','LA','LV','LB','LT','LU','MG','MY','MT','MA','MX','EG','MN','MZ','MM','NA','NP','NL','NZ','NG','NO','OM','PK','PS','PY','PE','PH','PL','PT','FR','PR','QA','DO','CZ','RO','RU','SA','SN','RS','SG','SK','SI','ES','LK','ZA','SU','SY','CH','SE','TW','TJ','TH','TM','TN','TR','UA','AE','UY','UZ','VE','VN','YE','JO','GR','ET','GH','HK','IN','ID','GB','IQ','IR','IE','IS','IL','IT','JM','JP','DE','GE','FI','HU','DK','EE','EC','KH','CY','MC','MK','ZW','ZM');
